mapper.select:
select id, report_name, download_url, status, down_status, report_type, group_count, is_del, create_time, update_time, JSON_EXTRACT(report_rules,'$.upload.user_type') as userType, JSON_EXTRACT(report_rules,'$.upload.dimensions_field') as dimensionsField from b_report_task where is_del = 1
and report_type = #{reportType}
and report_type in (7,8,9,10,11,12)
and report_name like CONCAT('%', #{reportName}, '%')
and JSON_EXTRACT(report_rules,'$.upload.user_type') = #{userType}
and JSON_EXTRACT(report_rules,'$.upload.dimensions_field') = #{dimensionsField}
GROUP BY create_time, id ORDER BY create_time DESC, id DESC
